export const envelope = [27, 18, 15];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];

  const voxels = [];
  for (let y = 0; y < H; y++) {
    const layer = [];
    for (let z = 0; z < D; z++) {
      layer.push(new Array(W).fill(null));
    }
    voxels.push(layer);
  }

  function put(x, y, z, block) {
    if (
      x >= 0 && x < W &&
      y >= 0 && y < H &&
      z >= 0 && z < D &&
      block !== undefined &&
      block !== null
    ) {
      voxels[y][z][x] = block;
    }
  }

  function clearCell(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      voxels[y][z][x] = null;
    }
  }

  function box(x0, y0, z0, x1, y1, z1, block) {
    for (let x = x0; x <= x1; x++) {
      for (let y = y0; y <= y1; y++) {
        for (let z = z0; z <= z1; z++) {
          put(x, y, z, block);
        }
      }
    }
  }

  function rewriteStates(block, desired) {
    const open = block.indexOf("[");
    if (open < 0) {
      let result = block + "[";
      for (let i = 0; i < desired.length; i++) {
        if (i > 0) {
          result += ",";
        }
        result += desired[i][0] + "=" + desired[i][1];
      }
      return result + "]";
    }

    const close = block.lastIndexOf("]");
    const end = close > open ? close : block.length;
    const id = block.slice(0, open);
    const raw = block.slice(open + 1, end);
    const names = [];
    const values = [];

    if (raw.length > 0) {
      const parts = raw.split(",");
      for (let i = 0; i < parts.length; i++) {
        const eq = parts[i].indexOf("=");
        if (eq > 0) {
          names.push(parts[i].slice(0, eq));
          values.push(parts[i].slice(eq + 1));
        }
      }
    }

    for (let i = 0; i < desired.length; i++) {
      const key = desired[i][0];
      const value = desired[i][1];
      let found = -1;

      for (let j = 0; j < names.length; j++) {
        if (names[j] === key) {
          found = j;
          break;
        }
      }

      if (found >= 0) {
        values[found] = value;
      } else {
        names.push(key);
        values.push(value);
      }
    }

    let result = id + "[";
    for (let i = 0; i < names.length; i++) {
      if (i > 0) {
        result += ",";
      }
      result += names[i] + "=" + values[i];
    }
    return result + "]";
  }

  const wood = api.theme.wood;
  const stone = api.theme.stone;
  const ground = api.theme.ground;

  const planks = wood.planks;
  const log = wood.log;
  const stripped = wood.stripped;
  const slab = wood.slab;
  const fence = wood.fence;
  const stonePrimary = stone.primary;
  const stoneAccent = stone.accent;
  const plinth = ground.plinth;
  const coping = ground.coping;

  const stairs = rewriteStates(wood.stairs, [
    ["facing", "east"],
    ["half", "bottom"],
    ["shape", "straight"],
    ["waterlogged", "false"]
  ]);

  const trapdoor = rewriteStates(wood.trapdoor, [
    ["facing", "north"],
    ["half", "bottom"],
    ["open", "false"],
    ["powered", "false"],
    ["waterlogged", "false"]
  ]);

  const terrainLevels = Array.from(
    { length: D },
    function () {
      return new Array(W).fill(null);
    }
  );

  function terrainLevel(x, z) {
    let level = terrainLevels[z][x];

    if (level === null) {
      let h = api.heightAt(x, z);

      if (typeof h !== "number" || !Number.isFinite(h)) {
        h = 0;
      }

      level = Math.ceil(h);

      if (level < 0) {
        level = 0;
      }

      if (level > 5) {
        level = 5;
      }

      terrainLevels[z][x] = level;
    }

    return level;
  }

  for (let x = 5; x <= 19; x++) {
    for (let y = 5; y <= 11; y++) {
      for (let z = 3; z <= 11; z++) {
        const hollow =
          x >= 7 && x <= 17 &&
          y >= 7 && y <= 10 &&
          z >= 5 && z <= 9;

        if (!hollow) {
          put(x, y, z, planks);
        }
      }
    }
  }

  for (let x = 5; x <= 19; x++) {
    for (let z = 3; z <= 11; z++) {
      put(x, 5, z, log);
      put(x, 11, z, log);
    }
  }

  for (let y = 6; y <= 10; y++) {
    for (let z = 3; z <= 11; z++) {
      put(5, y, z, log);
      put(19, y, z, log);
    }
  }

  box(4, 8, 4, 6, 10, 10, log);
  box(18, 8, 4, 20, 11, 10, log);

  for (let x = 7; x <= 17; x += 4) {
    for (let y = 7; y <= 10; y++) {
      put(x, y, 3, stripped);
    }
  }

  for (let x = 6; x <= 18; x++) {
    put(x, 12, 3, slab);
    put(x, 12, 11, slab);
  }

  const legs = [
    [6, 7, 4, 5],
    [6, 7, 9, 10],
    [17, 18, 4, 5],
    [17, 18, 9, 10]
  ];

  for (let i = 0; i < legs.length; i++) {
    const lx0 = legs[i][0];
    const lx1 = legs[i][1];
    const lz0 = legs[i][2];
    const lz1 = legs[i][3];

    for (let x = lx0 - 1; x <= lx1 + 1; x++) {
      for (let z = lz0 - 1; z <= lz1 + 1; z++) {
        const level = terrainLevel(x, z);

        for (let y = 0; y <= level; y++) {
          put(x, y, z, plinth);
        }

        const border =
          x === lx0 - 1 || x === lx1 + 1 ||
          z === lz0 - 1 || z === lz1 + 1;

        if (border && level + 1 < H) {
          put(x, level + 1, z, coping);
        }
      }
    }

    for (let x = lx0; x <= lx1; x++) {
      for (let z = lz0; z <= lz1; z++) {
        const level = terrainLevel(x, z);
        put(x, level, z, stonePrimary);

        for (let y = level + 1; y <= 6; y++) {
          put(x, y, z, log);
        }
      }
    }
  }

  box(18, 9, 4, 21, 12, 10, planks);
  box(19, 11, 5, 22, 14, 9, planks);
  box(21, 13, 4, 24, 15, 10, planks);
  box(23, 13, 5, 26, 14, 9, planks);
  box(24, 14, 5, 26, 15, 9, planks);

  box(22, 16, 4, 23, 17, 5, log);
  box(22, 16, 9, 23, 17, 10, log);

  for (let z = 5; z <= 9; z++) {
    put(26, 13, z, stripped);
    put(26, 14, z, stripped);
  }

  put(23, 14, 3, stoneAccent);
  put(23, 14, 11, stoneAccent);

  for (let x = 18; x <= 21; x++) {
    for (let y = 10; y <= 14; y++) {
      put(x, y, 3, stripped);
    }
  }

  box(4, 9, 6, 5, 10, 8, log);
  box(3, 8, 6, 4, 9, 8, stripped);
  box(2, 7, 6, 3, 8, 8, log);
  box(1, 6, 7, 2, 7, 7, stripped);
  put(1, 6, 7, fence);

  for (let x = 11; x <= 14; x++) {
    for (let z = 5; z <= 8; z++) {
      const frame =
        x === 11 || x === 14 ||
        z === 5 || z === 8;

      if (frame) {
        put(x, 6, z, stripped);
      }
    }
  }

  for (let x = 12; x <= 13; x++) {
    for (let z = 6; z <= 7; z++) {
      clearCell(x, 5, z);
      put(x, 6, z, trapdoor);
    }
  }

  for (let i = 0; i < 3; i++) {
    const x = 9 + i;
    const y = 9 - i;
    const z = 7;

    for (let supportY = 7; supportY < y; supportY++) {
      put(x, supportY, z, planks);
    }

    put(x, y, z, stairs);
  }

  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const block = voxels[y][z][x];

        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Trojan Horse of Troy",
    seatY: 0,
    anchors: {
      door: [12, 6, 6]
    },
    interiors: [
      {
        min: [7, 7, 5],
        max: [17, 10, 9],
        kind: "vault"
      }
    ]
  };
}

