export const envelope = [58, 16, 34];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];

  const wood = api.theme.wood;
  const ground = api.theme.ground;
  const seat = 3;
  const ropeBlock = wood.stripped;

  const sailWhite = "minecraft:white_wool";
  const sailWeathered = "minecraft:light_gray_wool";

  const put = (x, y, z, block) => {
    if (
      Number.isInteger(x) &&
      Number.isInteger(y) &&
      Number.isInteger(z) &&
      x >= 0 &&
      x < W &&
      y >= 0 &&
      y < H &&
      z >= 0 &&
      z < D
    ) {
      api.set(x, y, z, block);
    }
  };

  const terrain = new Array(W);
  const upperTerrain = Math.max(0, H - 10);

  for (let x = 0; x < W; x++) {
    terrain[x] = new Array(D);

    for (let z = 0; z < D; z++) {
      let h = Math.floor(api.heightAt(x, z));

      if (!Number.isFinite(h)) {
        h = 0;
      }

      let gy = seat + h;

      if (gy < 0) {
        gy = 0;
      }

      if (gy > upperTerrain) {
        gy = upperTerrain;
      }

      terrain[x][z] = gy;
    }
  }

  const groundY = (x, z) => terrain[x][z];

  for (let x = 1; x < W - 1; x++) {
    for (let dz = -1; dz <= 1; dz++) {
      const z = 16 + dz;
      const top = Math.min(H - 1, Math.max(seat - 1, groundY(x, z)));

      for (let y = 0; y <= top; y++) {
        put(x, y, z, y === top ? ground.coping : ground.plinth);
      }
    }

    for (let edge = 0; edge < 2; edge++) {
      const z = edge === 0 ? 14 : 18;
      const top = Math.max(0, Math.min(seat - 1, groundY(x, z)));

      for (let y = 0; y <= top; y++) {
        put(x, y, z, ground.plinth);
      }
    }
  }

  const ships = [
    {
      x0: 2,
      len: 17,
      cz: 15,
      beam: 4,
      pitch: 2,
      sheer: 2,
      heel: 0,
      mastHeight: 8,
      sailDir: 1,
      sailWidth: 6,
      tattered: false,
      damage: false,
      broken: false,
      oarLength: 4
    },
    {
      x0: 20,
      len: 17,
      cz: 16,
      beam: 3,
      pitch: -2,
      sheer: -2,
      heel: 1,
      mastHeight: 5,
      sailDir: -1,
      sailWidth: 3,
      tattered: true,
      damage: true,
      broken: true,
      oarLength: 3
    },
    {
      x0: 39,
      len: 17,
      cz: 17,
      beam: 4,
      pitch: 1,
      sheer: 2,
      heel: 0,
      mastHeight: 7,
      sailDir: -1,
      sailWidth: 5,
      tattered: true,
      damage: true,
      broken: false,
      oarLength: 4
    }
  ];

  function centerAt(spec, u) {
    const q = Math.max(0, Math.min(spec.len - 1, u));
    const t = q / (spec.len - 1);
    return spec.cz + Math.round(spec.sheer * (t - 0.5));
  }

  function baseNominal(spec, u) {
    const q = Math.max(0, Math.min(spec.len - 1, u));
    const t = q / (spec.len - 1);
    return seat + Math.round(spec.pitch * (t - 0.5));
  }

  function hullHalf(spec, u, level) {
    const q = Math.max(0, Math.min(spec.len - 1, u));
    const t = q / (spec.len - 1);
    const fullness = Math.sin(Math.PI * t);

    let shape;

    if (level === 0) {
      shape = 1.2;
    } else if (level === 1) {
      shape = Math.max(1, spec.beam - 2);
    } else if (level === 2) {
      shape = Math.max(2, spec.beam - 1);
    } else if (level === 3) {
      shape = spec.beam;
    } else {
      shape = Math.max(1, spec.beam - 1);
    }

    let half = Math.round(shape * (0.2 + 0.8 * fullness));

    if (level === 0) {
      half = Math.round(1.2 * fullness);
    }

    if (q > 0 && q < spec.len - 1 && half < 1) {
      half = 1;
    }

    return Math.max(0, Math.min(spec.beam, half));
  }

  function link(a, b, block) {
    let x = a[0];
    let y = a[1];
    let z = a[2];

    put(x, y, z, block);

    while (x !== b[0]) {
      x += x < b[0] ? 1 : -1;
      put(x, y, z, block);
    }

    while (y !== b[1]) {
      y += y < b[1] ? 1 : -1;
      put(x, y, z, block);
    }

    while (z !== b[2]) {
      z += z < b[2] ? 1 : -1;
      put(x, y, z, block);
    }
  }

  function ropePath(a, b) {
    let x = a[0];
    let y = a[1];
    let z = a[2];

    put(x, y, z, ropeBlock);

    const count = Math.max(
      Math.abs(b[0] - a[0]),
      Math.abs(b[1] - a[1]),
      Math.abs(b[2] - a[2])
    );

    for (let i = 1; i <= count; i++) {
      const f = i / count;
      const tx = Math.round(a[0] + (b[0] - a[0]) * f);
      const ty = Math.round(a[1] + (b[1] - a[1]) * f);
      const tz = Math.round(a[2] + (b[2] - a[2]) * f);

      while (x !== tx) {
        x += x < tx ? 1 : -1;
        put(x, y, z, ropeBlock);
      }

      while (y !== ty) {
        y += y < ty ? 1 : -1;
        put(x, y, z, ropeBlock);
      }

      while (z !== tz) {
        z += z < tz ? 1 : -1;
        put(x, y, z, ropeBlock);
      }
    }
  }

  function addKeel(spec) {
    let previous = null;

    for (let u = -2; u <= spec.len + 1; u++) {
      const x = spec.x0 + u;

      if (x < 0 || x >= W) {
        continue;
      }

      const q = Math.max(0, Math.min(spec.len - 1, u));
      const z = centerAt(spec, q);
      const gy = groundY(x, z);
      const y = Math.max(gy, baseNominal(spec, q));

      for (let yy = gy; yy < y; yy++) {
        put(x, yy, z, ground.plinth);
      }

      const position = [x, y, z];

      if (previous === null) {
        put(x, y, z, wood.log);
      } else {
        link(previous, position, wood.log);
      }

      if (x >= 1 && x < W - 1) {
        const nearest =
          z < 15
            ? 15
            : z > 17
              ? 17
              : z;

        const pathY = Math.max(seat - 1, groundY(x, nearest));
        link(position, [x, pathY, nearest], wood.log);
      }

      previous = position;
    }
  }

  function addHull(spec) {
    for (let u = 0; u < spec.len; u++) {
      const x = spec.x0 + u;
      const center = centerAt(spec, u);
      const maximumHalf = hullHalf(spec, u, 3);

      for (let rel = -maximumHalf; rel <= maximumHalf; rel++) {
        const z = center + rel;

        if (z < 0 || z >= D) {
          continue;
        }

        const gy = groundY(x, z);
        const base = Math.max(gy, baseNominal(spec, u));

        for (let yy = gy; yy < base; yy++) {
          put(x, yy, z, ground.plinth);
        }

        for (let level = 0; level <= 4; level++) {
          const half = hullHalf(spec, u, level);

          if (Math.abs(rel) > half) {
            continue;
          }

          const lift = spec.heel && rel > 0 ? 1 : 0;

          const damagedEdge =
            spec.damage &&
            level === 3 &&
            Math.abs(rel) === half &&
            (
              (u === 4 && rel < 0) ||
              (u === 10 && rel > 0) ||
              (u === 13 && rel < 0)
            );

          if (damagedEdge) {
            continue;
          }

          let block = wood.planks;

          if (level === 0) {
            block = wood.log;
          } else if (level === 1) {
            block = wood.stripped;
          } else if (level === 3 && Math.abs(rel) === half) {
            block = wood.stripped;
          }

          put(x, base + level + lift, z, block);
        }
      }
    }
  }

  function addProw(spec) {
    const endU = spec.len - 1;
    const endX = spec.x0 + endU;
    const z = centerAt(spec, endU);
    const base = Math.max(groundY(endX, z), baseNominal(spec, endU));

    for (let i = 0; i <= 2; i++) {
      const x = endX + i;

      for (let rise = 0; rise <= i; rise++) {
        put(x, base + 2 + rise, z, wood.log);
      }
    }

    if (endX + 1 < W) {
      put(endX + 1, base + 3, z - 1, wood.log);
      put(endX + 1, base + 3, z + 1, wood.log);
    }
  }

  function addOars(spec) {
    const slots = [2, 5, 8, 11, 14];

    for (let i = 0; i < slots.length; i++) {
      const u = slots[i];

      if (u >= spec.len - 1) {
        continue;
      }

      const x = spec.x0 + u;
      const center = centerAt(spec, u);
      const half = hullHalf(spec, u, 3);

      for (let side = -1; side <= 1; side += 2) {
        if (spec.damage && u === 11 && side < 0) {
          continue;
        }

        const edgeZ = center + side * half;
        const edgeBase = Math.max(
          groundY(x, edgeZ),
          baseNominal(spec, u)
        );
        const oarY = edgeBase + 3 + (spec.heel && side > 0 ? 1 : 0);

        for (let k = 0; k <= spec.oarLength; k++) {
          const block = k === spec.oarLength
            ? wood.planks
            : wood.stripped;

          put(x, oarY, edgeZ + side * k, block);
        }
      }
    }
  }

  function addDeckRails(spec) {
    for (let u = 1; u < spec.len - 1; u += 2) {
      const x = spec.x0 + u;
      const center = centerAt(spec, u);
      const half = hullHalf(spec, u, 4);

      for (let side = -1; side <= 1; side += 2) {
        const z = center + side * half;
        const base = Math.max(groundY(x, z), baseNominal(spec, u));
        const y = base + 4 + (spec.heel && side > 0 ? 1 : 0);

        put(x, y + 1, z, ropeBlock);
      }
    }
  }

  function mastInfo(spec) {
    const u = Math.floor((spec.len - 1) / 2);
    const x = spec.x0 + u;
    const z = centerAt(spec, u);
    const base = Math.max(groundY(x, z), baseNominal(spec, u));

    return {
      u,
      x,
      z,
      base,
      deck: base + 4
    };
  }

  function makeSail(info, yardY, direction, width, tattered) {
    const lower = info.deck + 2;

    if (yardY <= lower) {
      return;
    }

    const denominator = yardY - lower;
    const boomY = lower - 1;

    for (let k = 0; k <= width; k++) {
      put(info.x + direction * k, boomY, info.z, wood.stripped);
    }

    for (let y = lower; y < yardY; y++) {
      const span = Math.max(
        1,
        Math.round(width * (yardY - y) / denominator)
      );

      for (let k = 1; k <= span; k++) {
        const missing =
          tattered &&
          k === span &&
          ((y + k) % 4 === 0);

        if (missing) {
          continue;
        }

        const weathered =
          tattered &&
          ((y + k) % 3 === 0);

        put(
          info.x + direction * k,
          y,
          info.z,
          weathered ? sailWeathered : sailWhite
        );
      }
    }
  }

  function addRaisedMast(spec, info) {
    const start = info.deck + 1;
    const top = Math.min(
      H - 2,
      start + spec.mastHeight - 1
    );

    for (let y = start; y <= top; y++) {
      put(info.x, y, info.z, wood.log);
    }

    let yard = Math.max(info.deck + 3, top - 1);

    if (yard > top) {
      yard = top;
    }

    for (let dx = -4; dx <= 4; dx++) {
      put(info.x + dx, yard, info.z, wood.stripped);
    }

    const lowerY = Math.min(top, info.deck + 2);

    for (let dx = -2; dx <= 2; dx++) {
      put(info.x + dx, lowerY, info.z, wood.log);
    }

    makeSail(
      info,
      yard,
      spec.sailDir,
      spec.sailWidth,
      spec.tattered
    );

    return [info.x, yard, info.z];
  }

  function addBrokenMast(spec, info) {
    const lowerTop = Math.min(H - 4, info.deck + 4);

    for (let y = info.deck + 1; y <= lowerTop; y++) {
      put(info.x, y, info.z, wood.log);
    }

    const yard = Math.min(lowerTop, info.deck + 3);

    for (let dx = -3; dx <= 3; dx++) {
      put(info.x + dx, yard, info.z, wood.stripped);
    }

    makeSail(info, yard, -1, 3, true);

    let px = info.x;
    let py = lowerTop;

    for (let step = 0; step < 5; step++) {
      put(px, py, info.z, wood.log);

      if (step < 4) {
        px += 1;
        put(px, py, info.z, wood.log);

        if (step % 2 === 0) {
          py += 1;
          put(px, py, info.z, wood.log);
        }
      }
    }

    for (let dx = -2; dx <= 1; dx++) {
      put(px + dx, py, info.z, wood.stripped);
    }

    return [px, py, info.z];
  }

  function rigTarget(spec, u) {
    const x = spec.x0 + u;
    const center = centerAt(spec, u);
    const z = center - 1;
    const base = Math.max(groundY(x, z), baseNominal(spec, u));

    return [x, base + 3, z];
  }

  function addRigging(spec, info, upper) {
    const bow = rigTarget(spec, spec.len - 1);
    const stern = rigTarget(spec, 0);
    const start = [upper[0], upper[1], upper[2] - 1];

    ropePath(start, bow);
    ropePath(start, stern);
  }

  function addGangway(spec) {
    const u = 9;
    const x = spec.x0 + u;
    const center = centerAt(spec, u);
    const half = hullHalf(spec, u, 3);
    const edgeZ = center + half;
    const startZ = edgeZ + 1;
    const endZ = Math.min(D - 2, startZ + 6);

    const edgeBase = Math.max(
      groundY(x, edgeZ),
      baseNominal(spec, u)
    );

    const startY = edgeBase + 4 + (spec.heel ? 1 : 0);
    const endY = Math.min(
      H - 2,
      Math.max(seat - 1, groundY(x, endZ))
    );

    const length = endZ - startZ;
    let previousY = startY;

    for (let i = 0; i <= length; i++) {
      const z = startZ + i;
      const y = Math.round(
        startY + (endY - startY) * (i / length)
      );

      const low = Math.min(previousY, y);
      const high = Math.max(previousY, y);

      for (let yy = low; yy <= high; yy++) {
        put(x, yy, z, wood.planks);
      }

      previousY = y;
    }

    for (let dx = -1; dx <= 1; dx++) {
      for (let dz = -1; dz <= 1; dz++) {
        const xx = x + dx;
        const zz = endZ + dz;
        const top = Math.min(
          H - 1,
          Math.max(1, groundY(xx, zz))
        );

        for (let y = 0; y <= top; y++) {
          put(
            xx,
            y,
            zz,
            y === top ? ground.coping : ground.plinth
          );
        }
      }
    }

    put(x + 1, startY, startZ, ropeBlock);

    ropePath(
      [x + 1, startY, startZ],
      [x + 1, endY + 1, endZ]
    );

    return {
      x,
      endY,
      endZ
    };
  }

  for (let i = 0; i < ships.length; i++) {
    addKeel(ships[i]);
  }

  for (let i = 0; i < ships.length; i++) {
    addHull(ships[i]);
  }

  for (let i = 0; i < ships.length; i++) {
    addProw(ships[i]);
    addOars(ships[i]);
    addDeckRails(ships[i]);
  }

  const gangway = addGangway(ships[1]);

  for (let i = 0; i < ships.length; i++) {
    const spec = ships[i];
    const info = mastInfo(spec);
    const upper = spec.broken
      ? addBrokenMast(spec, info)
      : addRaisedMast(spec, info);

    addRigging(spec, info, upper);
  }

  const shoreY = Math.max(
    1,
    Math.min(H - 1, groundY(gangway.x, gangway.endZ))
  );

  return {
    name: "Beached Warships",
    seatY: seat,
    anchors: {
      boarding: [gangway.x, gangway.endY, gangway.endZ],
      shore: [gangway.x, shoreY, gangway.endZ]
    }
  };
}
